// Class 11 Physics Unit IX: Kinetic Theory of Gases (100% Exact Official NCERT Syllabus Alignment)
// High-Level Reference Book Content & NCERT Solutions (6 Self-Contained 3D Volumetric SVG Diagrams)

export const c11Phy9HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.7; font-size: 16px;\">\n\n  <!-- QUICK GLOSSARY & BASIC DEFINITIONS -->\n  <div style=\"background: rgba(66, 165, 245, 0.05); border: 1.5px solid #42A5F5; border-radius: 12px; padding: 16px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #42A5F5; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">📖 Quick Glossary & Basic Definitions</h2>\n    <p class=\"text-center\" style=\"color: #42A5F5; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Key Fundamental Terms & Concepts for Unit IX: Kinetic Theory of Gases</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 10px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #42A5F5; border-radius: 6px;\">\n        <b style='color: #42A5F5; display: block; margin-bottom: 3px;'>1. Perfect / Ideal Gas:</b>\n        <span style=\"color: #FFFFFF;\">A gas obeying ideal gas equation P V = n R T strictly at all pressures and temperatures.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #42A5F5; border-radius: 6px;\">\n        <b style='color: #42A5F5; display: block; margin-bottom: 3px;'>2. Gas Pressure (P):</b>\n        <span style=\"color: #FFFFFF;\">Macroscopic pressure resulting from continuous elastic molecular bombardment against container walls: P = 1/3 ρ v_rms<sup>2</sup>.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #42A5F5; border-radius: 6px;\">\n        <b style='color: #42A5F5; display: block; margin-bottom: 3px;'>3. Kinetic Temperature:</b>\n        <span style=\"color: #FFFFFF;\">Absolute temperature T is a direct measure of average translational kinetic energy per molecule: E_k = 3/2 k_B T.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #42A5F5; border-radius: 6px;\">\n        <b style='color: #42A5F5; display: block; margin-bottom: 3px;'>4. RMS Speed (v_rms):</b>\n        <span style=\"color: #FFFFFF;\">Square root of mean of squared speeds of gas molecules: v_rms = √(3 R T / M) = √(3 k_B T / m).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #42A5F5; border-radius: 6px;\">\n        <b style='color: #42A5F5; display: block; margin-bottom: 3px;'>5. Degrees of Freedom (f):</b>\n        <span style=\"color: #FFFFFF;\">Total number of independent coordinates or motion modes required to completely specify molecular position/configuration.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #42A5F5; border-radius: 6px;\">\n        <b style='color: #42A5F5; display: block; margin-bottom: 3px;'>6. Law of Equi-partition:</b>\n        <span style=\"color: #FFFFFF;\">In thermal equilibrium, total energy is shared equally among degrees of freedom, each contributing 1/2 k_B T per molecule.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #42A5F5; border-radius: 6px;\">\n        <b style='color: #42A5F5; display: block; margin-bottom: 3px;'>7. Mean Free Path (λ):</b>\n        <span style=\"color: #FFFFFF;\">Average distance traveled by a gas molecule between two successive elastic collisions: λ = 1 / (√2 π n d<sup>2</sup>).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #42A5F5; border-radius: 6px;\">\n        <b style='color: #42A5F5; display: block; margin-bottom: 3px;'>8. Universal Gas Constant (R):</b>\n        <span style=\"color: #FFFFFF;\">Universal constant of proportionality in ideal gas law: R = 8.314 J mol<sup>-1</sup> K<sup>-1</sup>.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #42A5F5; border-radius: 6px;\">\n        <b style='color: #42A5F5; display: block; margin-bottom: 3px;'>9. Boltzmann Constant (k_B):</b>\n        <span style=\"color: #FFFFFF;\">Gas constant per molecule: k_B = R / N_A = 1.3806 × 10<sup>-23</sup> J K<sup>-1</sup>.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #42A5F5; border-radius: 6px;\">\n        <b style='color: #42A5F5; display: block; margin-bottom: 3px;'>10. Avogadro's Number (N_A):</b>\n        <span style=\"color: #FFFFFF;\">Number of gas molecules in 1 mole of any substance: N_A = 6.022 × 10<sup>23</sup> mol<sup>-1</sup>.</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 1: EQUATION OF STATE OF A PERFECT GAS AND WORK DONE IN COMPRESSING A GAS (100% OFFICIAL SYLLABUS TITLE) -->\n  <h2 style=\"color: #42A5F5; border-bottom: 2px solid #42A5F5; padding-bottom: 6px; margin-top: 25px;\">1. Equation of State of a Perfect Gas and Work Done in Compressing a Gas</h2>\n  \n  \n  <div style=\"background: rgba(66, 165, 245, 0.06); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #42A5F5; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Equation of State of Perfect Gas):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The fundamental thermodynamic equation connecting pressure P, volume V, temperature T, and amount of gas n: P V = n R T = N k_B T.</p>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(66, 165, 245, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>P V = n R T &nbsp;|&nbsp; R = 8.314 J mol<sup>-1</sup> K<sup>-1</sup> &nbsp;|&nbsp; k<sub>B</sub> = 1.38 × 10<sup>-23</sup> J K<sup>-1</sup></b></div>\n\n  <p>An ideal or perfect gas is a theoretical gas whose molecules occupy negligible volume and exert no intermolecular forces. Real gases approximate ideal behavior at low pressures and high temperatures.</p>\n\n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #42A5F5; font-size: 15.5px; display: block; margin-bottom: 3px;\">• 1. Gas Laws Combination:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Boyle's Law (P V = Const at T), Charles's Law (V / T = Const at P), and Avogadro's Law (V ∝ n) combine to give P V = n R T.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #42A5F5; font-size: 15.5px; display: block; margin-bottom: 3px;\">• 2. Work Done in Compressing Gas:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">W = ∫<sub>V1</sub><sup>V2</sup> P dV = 2.303 n R T log<sub>10</sub>(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">V<sub>1</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">V<sub>2</sub></span>\n  </span>) &nbsp; (Isothermal Compression)</code></span>\n  </div>\n  </div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #42A5F5; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(66, 165, 245, 0.25);\">\n    <div style=\"color: #42A5F5; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Avogadro's Law & Ideal Gas Equation (P V = n R T = N k_B T)\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#42A5F5\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Avogadro's Law at STP</text>\n\n    <!-- Vessel 1: 1 Mole Gas A -->\n    <rect x=\"40\" y=\"70\" width=\"120\" height=\"160\" rx=\"8\" fill=\"rgba(66,165,245,0.1)\" stroke=\"#42A5F5\" stroke-width=\"2\"/>\n    <text x=\"100\" y=\"110\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Oxygen O₂</text>\n    <text x=\"100\" y=\"140\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14\">V = 22.4 L</text>\n    <text x=\"100\" y=\"170\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13.5\">N_A Molecules</text>\n\n    <!-- Vessel 2: 1 Mole Gas B -->\n    <rect x=\"205\" y=\"70\" width=\"120\" height=\"160\" rx=\"8\" fill=\"rgba(66,165,245,0.1)\" stroke=\"#42A5F5\" stroke-width=\"2\"/>\n    <text x=\"265\" y=\"110\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Helium He</text>\n    <text x=\"265\" y=\"140\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14\">V = 22.4 L</text>\n    <text x=\"265\" y=\"170\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13.5\">N_A Molecules</text>\n\n    <text x=\"182\" y=\"270\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Equal V at same P &amp; T contain equal N!</text>\n\n    <text x=\"182\" y=\"375\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Avogadro's Number N_A = 6.022 × 10²³ mol⁻¹</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Universal Gas Constants Summary Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#42A5F5\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#42A5F5\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Ideal Gas Equation &amp; Constants</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"90\" rx=\"8\" fill=\"rgba(66,165,245,0.1)\" stroke=\"#42A5F5\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#42A5F5\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Equation of State of Perfect Gas:</text>\n    <text x=\"182\" y=\"122\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">P V = n R T = N k_B T</text>\n\n    <rect x=\"10\" y=\"165\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"190\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Universal Gas Constant R:</text>\n    <text x=\"182\" y=\"225\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">R = 8.314 J mol⁻¹ K⁻¹</text>\n    <text x=\"182\" y=\"255\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"monospace\" font-size=\"13.5\">R = 1.987 cal mol⁻¹ K⁻¹ ≈ 2 cal/mol K</text>\n\n    <rect x=\"10\" y=\"290\" width=\"345\" height=\"120\" rx=\"8\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"315\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Boltzmann Constant k_B = R / N_A:</text>\n    <text x=\"182\" y=\"348\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">k_B = 1.3806 × 10⁻²³ J K⁻¹</text>\n    <text x=\"182\" y=\"380\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">• Relates macroscopic gas laws to molecular kinetics!</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 3D Vessels showing equal gas volumes at STP containing N_A = 6.022×10²³ molecules and universal gas constants.\n    </div>\n  </div>\n\n  <!-- SECTION 2: KINETIC THEORY OF GASES - ASSUMPTIONS AND CONCEPT OF PRESSURE EXERTED BY A GAS (100% OFFICIAL SYLLABUS TITLE) -->\n  <h2 style=\"color: #42A5F5; border-bottom: 2px solid #42A5F5; padding-bottom: 6px; margin-top: 30px;\">2. Kinetic Theory of Gases - Assumptions and Concept of Pressure Exerted by a Gas</h2>\n\n  \n  <div style=\"background: rgba(66, 165, 245, 0.06); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #42A5F5; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Pressure Exerted by a Gas):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The macroscopic force per unit area exerted on container walls due to continuous elastic collisions of gas molecules: P = 1/3 ρ v_rms<sup>2</sup>.</p>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(66, 165, 245, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>P = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">3</span>\n  </span> ρ v<sub>rms</sub><sup>2</sup> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">3</span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">N m</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">V</span>\n  </span> v<sub>rms</sub><sup>2</sup> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">3</span>\n  </span> E<sub>k</sub></b></div>\n\n  <h3 style=\"color: #42A5F5; margin-top: 20px;\">(i) Postulates of Kinetic Theory & Pressure Derivation</h3>\n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #42A5F5; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Point Mass Spheres:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Gas molecules are tiny hard spheres whose volume is negligible compared to total container volume.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #42A5F5; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Elastic Collisions:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Intermolecular and wall collisions are perfectly elastic, conserving total kinetic energy.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #42A5F5; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Momentum Transfer:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Molecule of mass m hitting wall at speed v_x rebounds with -v_x, imparting momentum Δp = 2 m v_x to the wall.</span>\n  </div>\n  </div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #42A5F5; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(66, 165, 245, 0.25);\">\n    <div style=\"color: #42A5F5; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Ideal Gas Cubic Container & Pressure Exertion Model\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"molGrad1\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#E0F7FA\"/>\n      <stop offset=\"40%\" stop-color=\"#42A5F5\"/>\n      <stop offset=\"100%\" stop-color=\"#0284C7\"/>\n    </radialGradient>\n    <marker id=\"arrowCyan1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#42A5F5\"/>\n    </marker>\n  </defs>\n\n  <!-- Left Side: 3D Cubic Gas Container (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#42A5F5\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Gas Molecule Collisions in Cube L³</text>\n\n    <!-- 3D Cube Perspective Box -->\n    <polygon points=\"60,140 180,80 300,140 180,200\" fill=\"rgba(66,165,245,0.08)\" stroke=\"#42A5F5\" stroke-width=\"1.5\"/>\n    <polygon points=\"60,140 180,200 180,330 60,270\" fill=\"rgba(66,165,245,0.12)\" stroke=\"#42A5F5\" stroke-width=\"1.5\"/>\n    <polygon points=\"180,200 300,140 300,270 180,330\" fill=\"rgba(66,165,245,0.05)\" stroke=\"#42A5F5\" stroke-width=\"1.5\"/>\n\n    <!-- Molecule m hitting right wall area A = L² -->\n    <circle cx=\"210\" cy=\"220\" r=\"10\" fill=\"url(#molGrad1)\"/>\n    <line x1=\"210\" y1=\"220\" x2=\"285\" y2=\"220\" stroke=\"#76FF03\" stroke-width=\"3\" marker-end=\"url(#arrowCyan1)\"/>\n    <text x=\"240\" y=\"210\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">v_x →</text>\n\n    <polygon points=\"300,140 300,270 180,330 180,200\" fill=\"rgba(255,81,47,0.25)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"250\" y=\"270\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Wall Area A = L²</text>\n\n    <text x=\"182\" y=\"375\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Momentum Change per Collision Δp = 2 m v_x</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Gas Pressure Formulae Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#42A5F5\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#42A5F5\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Pressure Exerted by Ideal Gas</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"100\" rx=\"8\" fill=\"rgba(66,165,245,0.1)\" stroke=\"#42A5F5\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#42A5F5\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Pressure Derivation Equation:</text>\n    <text x=\"182\" y=\"122\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">P = ⅓ ρ v_rms² = ⅓ (N m / V) v_rms²</text>\n\n    <rect x=\"10\" y=\"175\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"200\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Pressure &amp; Kinetic Energy Relation:</text>\n    <text x=\"182\" y=\"235\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">P = ⅔ E_k &nbsp; (Energy Density E_k)</text>\n    <text x=\"182\" y=\"265\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"13\">✓ Pressure equals 2/3 of translational KE per unit volume!</text>\n\n    <rect x=\"10\" y=\"300\" width=\"345\" height=\"115\" rx=\"8\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#FFD700\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"325\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Key Assumptions of Kinetic Theory:</text>\n    <text x=\"25\" y=\"353\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\">• Gas consists of tiny elastic point-mass spheres</text>\n    <text x=\"25\" y=\"375\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\">• Zero intermolecular forces except during instant collision</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 3D Cube L³ showing molecule momentum transfer Δp = 2 m v_x upon elastic collision deriving P = 1/3 ρ v_rms².\n    </div>\n  </div>\n\n  <!-- SECTION 3: KINETIC INTERPRETATION OF TEMPERATURE AND RMS SPEED OF GAS MOLECULES (100% OFFICIAL SYLLABUS TITLE) -->\n  <h2 style=\"color: #42A5F5; border-bottom: 2px solid #42A5F5; padding-bottom: 6px; margin-top: 30px;\">3. Kinetic Interpretation of Temperature and RMS Speed of Gas Molecules</h2>\n\n  \n  <div style=\"background: rgba(66, 165, 245, 0.06); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #42A5F5; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Kinetic Interpretation of Temperature):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">States that absolute temperature T is directly proportional to the average translational kinetic energy per molecule of gas: E_k = 3/2 k_B T.</p>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(66, 165, 245, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>v<sub>rms</sub> = √(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">3 R T</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M</span>\n  </span>) = √(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">3 k<sub>B</sub> T</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m</span>\n  </span>) &nbsp;|&nbsp; Ratio v<sub>mp</sub> : v<sub>avg</sub> : v<sub>rms</sub> = 1 : 1.128 : 1.225</b></div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #42A5F5; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(66, 165, 245, 0.25);\">\n    <div style=\"color: #42A5F5; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Maxwell-Boltzmann Speed Distribution Curve (v_mp, v_avg, v_rms)\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <!-- Left Side: Maxwell Distribution Curve (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#42A5F5\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Maxwell-Boltzmann Speed Distribution</text>\n\n    <!-- Axes -->\n    <line x1=\"50\" y1=\"330\" x2=\"340\" y2=\"330\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <line x1=\"50\" y1=\"330\" x2=\"50\" y2=\"60\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <text x=\"345\" y=\"335\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">Speed v</text>\n    <text x=\"40\" y=\"50\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">N(v)</text>\n\n    <!-- Distribution Curve -->\n    <path d=\"M 50 330 Q 130 70 220 220 Q 280 300 330 325\" fill=\"none\" stroke=\"#42A5F5\" stroke-width=\"3.5\"/>\n\n    <!-- Speed Lines: v_mp, v_avg, v_rms -->\n    <line x1=\"125\" y1=\"95\" x2=\"125\" y2=\"330\" stroke=\"#FF512F\" stroke-width=\"2\" stroke-dasharray=\"3,3\"/>\n    <text x=\"110\" y=\"85\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">v_mp</text>\n\n    <line x1=\"145\" y1=\"115\" x2=\"145\" y2=\"330\" stroke=\"#FFD700\" stroke-width=\"2\" stroke-dasharray=\"3,3\"/>\n    <text x=\"140\" y=\"105\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">v_avg</text>\n\n    <line x1=\"168\" y1=\"145\" x2=\"168\" y2=\"330\" stroke=\"#76FF03\" stroke-width=\"2\" stroke-dasharray=\"3,3\"/>\n    <text x=\"172\" y=\"135\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">v_rms</text>\n\n    <text x=\"182\" y=\"375\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Ratio v_mp : v_avg : v_rms = 1 : 1.128 : 1.225</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Speed Formulae Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#42A5F5\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#42A5F5\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Molecular Speed Equations</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"90\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Root-Mean-Square Speed (v_rms):</text>\n    <text x=\"182\" y=\"120\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">v_rms = √(3 R T / M) = √(3 k_B T / m)</text>\n\n    <rect x=\"10\" y=\"165\" width=\"345\" height=\"90\" rx=\"8\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#FFD700\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"190\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Average Speed (v_avg):</text>\n    <text x=\"182\" y=\"225\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">v_avg = √(8 R T / π M)</text>\n\n    <rect x=\"10\" y=\"270\" width=\"345\" height=\"140\" rx=\"8\" fill=\"rgba(255,81,47,0.1)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"295\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Most Probable Speed (v_mp):</text>\n    <text x=\"182\" y=\"330\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">v_mp = √(2 R T / M)</text>\n    <text x=\"182\" y=\"365\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Kinetic Temp: E_k = 🔍 3/2 k_B T</text>\n    <text x=\"182\" y=\"390\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"12.5\">• At Absolute Zero T=0 K, all molecular motion stops!</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Speed distribution graph showing Most Probable v_mp, Average v_avg, and RMS v_rms speed peaks.\n    </div>\n  </div>\n\n  <!-- SECTION 4: DEGREES OF FREEDOM, LAW OF EQUI-PARTITION OF ENERGY AND SPECIFIC HEAT CAPACITIES (100% OFFICIAL SYLLABUS TITLE) -->\n  <h2 style=\"color: #42A5F5; border-bottom: 2px solid #42A5F5; padding-bottom: 6px; margin-top: 30px;\">4. Degrees of Freedom, Law of Equi-partition of Energy and Specific Heat Capacities</h2>\n\n  \n  <div style=\"background: rgba(66, 165, 245, 0.06); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #42A5F5; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Law of Equi-partition of Energy):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">States that in thermal equilibrium, total energy of a gas is divided equally among all its degrees of freedom, each carrying energy 1/2 k_B T per molecule.</p>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(66, 165, 245, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>C<sub>v</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> R &nbsp;|&nbsp; C<sub>p</sub> = ( <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> + 1 ) R &nbsp;|&nbsp; γ = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">C<sub>p</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">C<sub>v</sub></span>\n  </span> = 1 + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">f</span>\n  </span></b></div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #42A5F5; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(66, 165, 245, 0.25);\">\n    <div style=\"color: #42A5F5; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Degrees of Freedom (f) for Monoatomic, Diatomic & Polyatomic\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 460\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <g transform=\"translate(20, 20)\">\n    <!-- Card 1: Monoatomic Gas -->\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"195\" rx=\"12\" fill=\"rgba(66,165,245,0.08)\" stroke=\"#42A5F5\" stroke-width=\"1.5\"/>\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#42A5F5\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">1. Monoatomic Gas (He, Ne, Ar)</text>\n    <text x=\"182\" y=\"65\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">Degrees of Freedom f = 3</text>\n    <text x=\"25\" y=\"105\" fill=\"#CBD5E1\" font-family=\"sans-serif\" font-size=\"13.5\">• 3 Translational degrees (x, y, z axes)</text>\n    <text x=\"25\" y=\"130\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13.5\">• Molar internal energy U = (3/2) R T</text>\n  </g>\n\n  <g transform=\"translate(415, 20)\">\n    <!-- Card 2: Rigid Diatomic Gas -->\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"195\" rx=\"12\" fill=\"rgba(118,255,3,0.08)\" stroke=\"#76FF03\" stroke-width=\"1.5\"/>\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">2. Diatomic Gas Rigid (O₂, N₂, H₂)</text>\n    <text x=\"182\" y=\"65\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">Degrees of Freedom f = 5</text>\n    <text x=\"25\" y=\"105\" fill=\"#CBD5E1\" font-family=\"sans-serif\" font-size=\"13.5\">• 3 Translational + 2 Rotational degrees</text>\n    <text x=\"25\" y=\"130\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"13.5\">• Molar internal energy U = (5/2) R T</text>\n  </g>\n\n  <g transform=\"translate(20, 235)\">\n    <!-- Card 3: Non-Rigid Diatomic (Vibrating) -->\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"195\" rx=\"12\" fill=\"rgba(255,215,0,0.08)\" stroke=\"#FFD700\" stroke-width=\"1.5\"/>\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">3. Diatomic Gas at High Temp (Vibrational)</text>\n    <text x=\"182\" y=\"65\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">Degrees of Freedom f = 7</text>\n    <text x=\"25\" y=\"105\" fill=\"#CBD5E1\" font-family=\"sans-serif\" font-size=\"13.5\">• 3 Translational + 2 Rotational + 2 Vibrational</text>\n    <text x=\"25\" y=\"130\" fill=\"#FF8A65\" font-family=\"sans-serif\" font-size=\"13.5\">• Molar internal energy U = (7/2) R T</text>\n  </g>\n\n  <g transform=\"translate(415, 235)\">\n    <!-- Card 4: Polyatomic Gas -->\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"195\" rx=\"12\" fill=\"rgba(255,81,47,0.08)\" stroke=\"#FF512F\" stroke-width=\"1.5\"/>\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">4. Polyatomic Non-Linear Gas (H₂O, CH₄)</text>\n    <text x=\"182\" y=\"65\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">Degrees of Freedom f = 6</text>\n    <text x=\"25\" y=\"105\" fill=\"#CBD5E1\" font-family=\"sans-serif\" font-size=\"13.5\">• 3 Translational + 3 Rotational degrees</text>\n    <text x=\"25\" y=\"130\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"13.5\">• Molar internal energy U = 3 R T</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 4 3D cards comparing degrees of freedom f=3 (Mono), f=5 (Diatomic rigid), f=7 (Vibrating), f=6 (Polyatomic).\n    </div>\n  </div>\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #42A5F5; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(66, 165, 245, 0.25);\">\n    <div style=\"color: #42A5F5; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Law of Equi-partition of Energy & Molar Specific Heat Capacities\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <!-- Left Side: Law Statement (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#42A5F5\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Law of Equi-partition of Energy</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"120\" rx=\"8\" fill=\"rgba(66,165,245,0.1)\" stroke=\"#42A5F5\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#42A5F5\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Law Statement:</text>\n    <text x=\"182\" y=\"118\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13.5\">For a dynamical system in thermal equilibrium, total energy is distributed equally among all degrees of freedom.</text>\n\n    <rect x=\"10\" y=\"200\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"225\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Energy per Degree of Freedom:</text>\n    <text x=\"182\" y=\"260\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">E_degree = ½ k_B T &nbsp; (Per Molecule)</text>\n\n    <text x=\"182\" y=\"375\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Molar Energy U = (f / 2) R T</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Specific Heat Capacities Summary (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#42A5F5\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#42A5F5\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Specific Heat Capacities (C_v, C_p, γ)</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"90\" rx=\"8\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#FFD700\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">C_v &amp; C_p Equations:</text>\n    <text x=\"182\" y=\"118\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16.5\" font-weight=\"bold\">C_v = (f / 2) R &nbsp;|&nbsp; C_p = (f / 2 + 1) R</text>\n\n    <rect x=\"10\" y=\"165\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"190\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Adiabatic Index γ = C_p / C_v:</text>\n    <text x=\"182\" y=\"225\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">γ = 1 + (2 / f)</text>\n    <text x=\"182\" y=\"255\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"13\">✓ Mono (f=3): γ=1.67 | Di (f=5): γ=1.40 | Poly (f=6): γ=1.33</text>\n\n    <rect x=\"10\" y=\"290\" width=\"345\" height=\"120\" rx=\"8\" fill=\"rgba(255,81,47,0.1)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"315\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Mayer's Formula Verification:</text>\n    <text x=\"182\" y=\"348\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16.5\" font-weight=\"bold\">C_p - C_v = R</text>\n    <text x=\"182\" y=\"380\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">• Valid for all ideal gas molecular structures!</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Energy partition 1/2 k_B T per degree of freedom deriving molar heat capacities C_v, C_p, and adiabatic index γ.\n    </div>\n  </div>\n\n  <!-- SECTION 5: CONCEPT OF MEAN FREE PATH AND AVOGADRO'S NUMBER (100% OFFICIAL SYLLABUS TITLE) -->\n  <h2 style=\"color: #42A5F5; border-bottom: 2px solid #42A5F5; padding-bottom: 6px; margin-top: 30px;\">5. Concept of Mean Free Path and Avogadro's Number</h2>\n\n  \n  <div style=\"background: rgba(66, 165, 245, 0.06); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #42A5F5; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Mean Free Path (λ)):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The average distance traveled by a gas molecule between two successive collisions: λ = 1 / (√2 π n d<sup>2</sup>).</p>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(66, 165, 245, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>λ = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√2 π n d<sup>2</sup></span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">k<sub>B</sub> T</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√2 π d<sup>2</sup> P</span>\n  </span> &nbsp;|&nbsp; N<sub>A</sub> = 6.022 × 10<sup>23</sup> mol<sup>-1</sup></b></div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #42A5F5; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(66, 165, 245, 0.25);\">\n    <div style=\"color: #42A5F5; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Mean Free Path (λ) & Collision Cylinder Model\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"molGrad5\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#E0F7FA\"/>\n      <stop offset=\"40%\" stop-color=\"#42A5F5\"/>\n      <stop offset=\"100%\" stop-color=\"#0284C7\"/>\n    </radialGradient>\n  </defs>\n\n  <!-- Left Side: Collision Cylinder Model (Width 365, Center x = 182) -->\n  <g transform=\"translate(20, 20)\">\n    <text x=\"182\" y=\"30\" text-anchor=\"middle\" fill=\"#42A5F5\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Collision Cylinder &amp; Zig-Zag Trajectory</text>\n\n    <!-- Collision Cylinder of Diameter 2d -->\n    <rect x=\"50\" y=\"160\" width=\"260\" height=\"80\" rx=\"40\" fill=\"rgba(66,165,245,0.12)\" stroke=\"#42A5F5\" stroke-width=\"2\"/>\n\n    <!-- Central Moving Molecule -->\n    <circle cx=\"180\" cy=\"200\" r=\"14\" fill=\"url(#molGrad5)\"/>\n\n    <!-- Target Molecule Collisions -->\n    <circle cx=\"90\" cy=\"180\" r=\"14\" fill=\"#FF512F\"/>\n    <circle cx=\"270\" cy=\"220\" r=\"14\" fill=\"#FF512F\"/>\n\n    <!-- Trajectory Path λ -->\n    <line x1=\"90\" y1=\"180\" x2=\"180\" y2=\"200\" stroke=\"#76FF03\" stroke-width=\"2.5\"/>\n    <line x1=\"180\" y1=\"200\" x2=\"270\" y2=\"220\" stroke=\"#76FF03\" stroke-width=\"2.5\"/>\n\n    <text x=\"135\" y=\"175\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13.5\" font-weight=\"bold\">Path λ₁</text>\n    <text x=\"225\" y=\"235\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13.5\" font-weight=\"bold\">Path λ₂</text>\n\n    <text x=\"182\" y=\"375\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Mean Free Path λ = Average Free Distance</text>\n  </g>\n\n  <!-- Vertical Divider -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"450\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Side: Mean Free Path Equations Card (Width 365, Center x = 182) -->\n  <g transform=\"translate(415, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"430\" rx=\"12\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#42A5F5\" stroke-width=\"1.8\"/>\n    <text x=\"182\" y=\"35\" text-anchor=\"middle\" fill=\"#42A5F5\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Mean Free Path Formulae</text>\n\n    <rect x=\"10\" y=\"60\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(66,165,245,0.1)\" stroke=\"#42A5F5\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"85\" text-anchor=\"middle\" fill=\"#42A5F5\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Mean Free Path Equation (λ):</text>\n    <text x=\"182\" y=\"122\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">λ = 1 / (√2 π n d²)</text>\n    <text x=\"182\" y=\"152\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\">n = Number density | d = Molecular diameter</text>\n\n    <rect x=\"10\" y=\"185\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#FFD700\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"210\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Dependence on Pressure &amp; Temp:</text>\n    <text x=\"182\" y=\"245\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"17\" font-weight=\"bold\">λ = k_B T / (√2 π d² P)</text>\n    <text x=\"182\" y=\"275\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"13\">✓ λ ∝ T (at const P) &nbsp;|&nbsp; λ ∝ 1/P (at const T)</text>\n\n    <rect x=\"10\" y=\"305\" width=\"345\" height=\"110\" rx=\"8\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.2\"/>\n    <text x=\"182\" y=\"330\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Dependence on Gas Density ρ:</text>\n    <text x=\"182\" y=\"362\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16.5\" font-weight=\"bold\">λ = m / (√2 π d² ρ) &nbsp; ⇒ &nbsp; λ ∝ 1/ρ</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Collision cross-section cylinder of diameter 2d and zig-zag free path trajectory deriving λ = 1 / (√2 π n d²).\n    </div>\n  </div>\n\n  <!-- QUICK REVISION CHEAT SHEET -->\n  <div style=\"background: rgba(66, 165, 245, 0.05); border: 1.5px solid #42A5F5; border-radius: 12px; padding: 16px; margin-top: 35px; margin-bottom: 15px;\">\n    <h2 class=\"text-center\" style=\"color: #42A5F5; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">⚡ Quick Revision Cheat Sheet</h2>\n    <p class=\"text-center\" style=\"color: #42A5F5; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Key Formulae, Molecular Speeds & Equi-partition Summary for Unit IX</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 10px; font-size: 14px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #42A5F5; border-radius: 6px;\">\n        <b style='color: #42A5F5; display: block; margin-bottom: 3px;'>• Ideal Gas Pressure:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">P = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">3</span>\n  </span> ρ v<sub>rms</sub><sup>2</sup> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">3</span>\n  </span> E<sub>k</sub><br>P V = n R T = N k<sub>B</sub> T</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #42A5F5; border-radius: 6px;\">\n        <b style='color: #42A5F5; display: block; margin-bottom: 3px;'>• Molecular Speeds:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">v<sub>rms</sub> = √(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">3 R T</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M</span>\n  </span>)<br>v<sub>avg</sub> = √(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">8 R T</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">π M</span>\n  </span>) &nbsp;|&nbsp; v<sub>mp</sub> = √(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 R T</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M</span>\n  </span>)</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #42A5F5; border-radius: 6px;\">\n        <b style='color: #42A5F5; display: block; margin-bottom: 3px;'>• Equi-partition Energy:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">E<sub>degree</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> k<sub>B</sub> T<br>U = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> R T</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #42A5F5; border-radius: 6px;\">\n        <b style='color: #42A5F5; display: block; margin-bottom: 3px;'>• Molar Specific Heats:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">C<sub>v</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> R &nbsp;|&nbsp; C<sub>p</sub> = (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> + 1) R<br>γ = 1 + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">f</span>\n  </span></span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #42A5F5; border-radius: 6px;\">\n        <b style='color: #42A5F5; display: block; margin-bottom: 3px;'>• Mean Free Path:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">λ = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√2 π n d<sup>2</sup></span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">k<sub>B</sub> T</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">√2 π d<sup>2</sup> P</span>\n  </span><br>λ ∝ T / P</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #42A5F5; border-radius: 6px;\">\n        <b style='color: #42A5F5; display: block; margin-bottom: 3px;'>• Universal Constants:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">R = 8.314 J mol<sup>-1</sup> K<sup>-1</sup><br>k<sub>B</sub> = 1.38 × 10<sup>-23</sup> J K<sup>-1</sup> &nbsp;|&nbsp; N<sub>A</sub> = 6.022 × 10<sup>23</sup></span>\n      </div>\n    </div>\n  </div>\n\n</div>\n";

export const c11Phy9HtmlSolutions = "<style>\n    p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) { text-align: justify !important; }\n    h1, h2, h3, h4, h5, h6 { text-align: left; }\n    .text-center { text-align: center !important; }\n  </style>\n  <div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.7; font-size: 16px;\">\n  <h1 style=\"color: #42A5F5; border-bottom: 2.5px solid #42A5F5; padding-bottom: 6px; margin-top: 10px;\">NCERT & Textbook Standard Exercise Solutions — Unit IX: Kinetic Theory of Gases</h1><h2 style=\"color: #42A5F5; border-bottom: 2px solid #42A5F5; padding-bottom: 6px; margin-top: 25px;\">SECTION 1: MULTIPLE CHOICE QUESTIONS (MCQs 1 - 25)</h2>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q1: The pressure exerted by an ideal gas in terms of rms speed is given by:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) P = ⅓ ρ v_rms²</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) P = ½ ρ v_rms²</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) P = ⅔ ρ v_rms²</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) P = ρ v_rms²</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> By Kinetic Theory derivation P = ⅓ ρ v_rms².</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q2: Average translational kinetic energy per molecule of an ideal gas at temperature T is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) ½ k_B T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 3/2 k_B T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 5/2 k_B T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) k_B T</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Translational KE per molecule = 3 × (½ k_B T) = 3/2 k_B T.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q3: At what temperature does all molecular translational motion of an ideal gas cease?</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 0 °C</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 273 K</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 0 K (-273.15 °C)</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) -100 °C</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (c)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> At Absolute Zero (0 K), v_rms = 0 and translational kinetic energy becomes zero.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q4: The ratio of most probable speed, average speed, and rms speed (v_mp : v_avg : v_rms) is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 1 : 1.128 : 1.225</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 1.225 : 1.128 : 1</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 1 : 1 : 1</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 1.414 : 1.60 : 1.73</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> v_mp = √(2RT/M) ≈ 1.414, v_avg = √(8RT/πM) ≈ 1.596, v_rms = √(3RT/M) ≈ 1.732. Ratio is 1 : 1.128 : 1.225.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q5: The number of degrees of freedom for a rigid diatomic gas molecule like N₂ is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 3</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 5</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 6</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 7</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Diatomic rigid molecule has 3 translational + 2 rotational degrees of freedom = 5.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q6: According to the Law of Equi-partition of Energy, energy per degree of freedom per molecule is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) k_B T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) ½ k_B T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 3/2 k_B T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) R T</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Each degree of freedom contributes ½ k_B T energy per molecule in thermal equilibrium.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q7: The ratio of molar heat capacities γ = C_p / C_v for a monoatomic gas like Helium is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 1.40</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 1.67</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 1.33</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 1.25</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Monoatomic f = 3 ⇒ C_v = 3/2 R, C_p = 5/2 R ⇒ γ = 5/3 ≈ 1.67.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q8: Mean free path λ of a gas molecule depends on molecular diameter d as:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) λ ∝ d</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) λ ∝ 1/d</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) λ ∝ 1/d²</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) λ ∝ d²</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (c)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Mean free path formula λ = 1 / (√2 π n d²), so λ is inversely proportional to d².</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q9: If temperature of a gas is increased from 27°C to 927°C, its rms speed becomes:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Doubled</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Tripled</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Quadrupled</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Halved</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> T₁ = 300 K, T₂ = 1200 K (4 times T₁). Since v_rms ∝ √T, v_rms' = √4 v_rms = 2 v_rms.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q10: The value of Universal Gas Constant R is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 8.314 J mol⁻¹ K⁻¹</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 1.38 × 10⁻²³ J K⁻¹</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 6.022 × 10²³ mol⁻¹</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 9.8 m s⁻²</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Universal gas constant R = 8.314 J mol⁻¹ K⁻¹.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q11: The relation between Boltzmann constant k_B, Universal gas constant R, and Avogadro's number N_A is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) k_B = R N_A</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) k_B = R / N_A</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) k_B = N_A / R</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) k_B = R + N_A</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Boltzmann constant is the gas constant per molecule: k_B = R / N_A.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q12: The pressure of a gas inside a closed container is doubled at constant volume. Its rms speed increases by factor of:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 2</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) √2</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 4</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) ½</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> P ∝ T at constant V. Doubling P doubles T. Since v_rms ∝ √T, v_rms increases by √2.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q13: For a polyatomic non-linear gas with 6 degrees of freedom, the adiabatic index γ is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 1.67</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 1.40</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 1.33</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 1.20</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (c)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> γ = 1 + 2/f = 1 + 2/6 = 1 + 1/3 = 4/3 ≈ 1.33.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q14: Mean free path λ of a gas at constant volume varies with absolute temperature T as:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) λ ∝ T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) λ ∝ √T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Independent of T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) λ ∝ 1/T</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (c)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> At constant volume, number density n = N/V is constant. Since λ = 1/(√2 π n d²), λ is independent of T.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q15: Two gases Oxygen (M=32) and Hydrogen (M=2) are at same temperature T. Ratio of their rms speeds (v_O2 / v_H2) is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 1 : 4</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 4 : 1</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 1 : 16</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 16 : 1</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> v_rms ∝ 1/√M. Ratio v_O2 / v_H2 = √(M_H2 / M_O2) = √(2/32) = √(1/16) = 1/4.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q16: Which gas law states that equal volumes of all gases at same P and T contain equal number of molecules?</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Boyle's Law</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Charles's Law</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Avogadro's Law</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Graham's Law</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (c)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Avogadro's Hypothesis states equal V at same P and T contains equal N = N_A.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q17: The mean kinetic energy per mole of a monoatomic gas is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) ½ R T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 3/2 R T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 5/2 R T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 3 R T</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> Per mole energy U = N_A × (3/2 k_B T) = 3/2 R T.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q18: Mean free path of gas molecules at constant temperature varies with pressure P as:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) λ ∝ P</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) λ ∝ 1/P</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) λ ∝ P²</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Independent of P</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> At constant T, number density n = P / (k_B T), so λ = k_B T / (√2 π d² P) ∝ 1/P.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q19: What is the number of degrees of freedom for a non-rigid vibrating diatomic molecule at high temperature?</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 3</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 5</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 6</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 7</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (d)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> 3 translational + 2 rotational + 2 vibrational (KE + PE) = 7 degrees of freedom.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q20: If pressure of a gas is held constant, its density ρ varies with absolute temperature T as:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) ρ ∝ T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) ρ ∝ 1/T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) ρ ∝ √T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Independent of T</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> P = (ρ/M) R T ⇒ ρ = P M / (R T) ∝ 1/T.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q21: The value of Boltzmann constant k_B is approximately:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 1.38 × 10⁻²³ J K⁻¹</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 8.314 J K⁻¹</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 6.022 × 10²³ J K⁻¹</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 1.6 × 10⁻¹⁹ J K⁻¹</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> k_B = R / N_A = 8.314 / (6.022×10²³) = 1.3806 × 10⁻²³ J/K.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q22: A vessel contains mixture of 1 mole He and 1 mole O₂ at temp T. Total internal energy of mixture is:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 3 R T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 4 R T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 5 R T</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 8/2 R T</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> U_He = 3/2 R T, U_O2 = 5/2 R T. Total U = 3/2 R T + 5/2 R T = 4 R T.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q23: At what temperature will rms speed of Oxygen molecules equal that of Hydrogen molecules at -73°C (200 K)?</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) 800 K</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) 1600 K</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) 3200 K</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) 400 K</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (c)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> T_O2 / M_O2 = T_H2 / M_H2 ⇒ T_O2 / 32 = 200 / 2 ⇒ T_O2 = 16 × 200 = 3200 K.</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q24: The dimensions of Boltzmann Constant k_B are:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) [M L² T⁻² K⁻¹]</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) [M L T⁻² K⁻¹]</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) [M L² T⁻¹ K⁻¹]</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) [M L⁻¹ T⁻² K⁻¹]</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (a)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> k_B = Energy / Temp ⇒ [M L² T⁻²][K⁻¹] = [M L² T⁻² K⁻¹].</div>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 15px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q25: In a gas of molecular diameter d = 2 Å, if density is doubled at constant T, mean free path λ will:</b>\n      <div style=\"margin: 10px 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\">\n        <div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(a) Double</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(b) Halve</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(c) Quadruple</div><div class=\"mcq-option\" style=\"color: #E0E0E0; font-size: 15px;\">(d) Remain constant</div>\n      </div>\n      <div style=\"margin-top: 8px; color: #42A5F5; font-weight: bold;\">✓ Answer: (b)</div>\n      <div style=\"margin-top: 4px; color: #CBD5E1; font-size: 14.5px;\">💡 <b>Explanation:</b> λ ∝ 1/ρ. Doubling density ρ halves the mean free path λ.</div>\n    </div><h2 style=\"color: #42A5F5; border-bottom: 2px solid #42A5F5; padding-bottom: 6px; margin-top: 30px;\">SECTION 2: VERY SHORT ANSWER QUESTIONS (VSAs 26 - 55)</h2>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q26: Write the equation of state for n moles of an ideal gas.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> P V = n R T (or P V = N k_B T).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q27: State Boyle's Law.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> For a given mass of gas at constant temperature, pressure is inversely proportional to volume (P V = Constant).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q28: State Charles's Law.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> For a given mass of gas at constant pressure, volume is directly proportional to absolute temperature (V / T = Constant).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q29: Define an ideal gas.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> A gas that strictly obeys equation P V = n R T at all pressures and temperatures.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q30: Write the expression for pressure exerted by an ideal gas in terms of density ρ and rms speed v_rms.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> P = ⅓ ρ v_rms².</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q31: What is the kinetic interpretation of absolute temperature T?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Absolute temperature is a direct measure of average translational kinetic energy per molecule (E_k = 3/2 k_B T).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q32: Define Root-Mean-Square (RMS) speed of gas molecules.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> The square root of the mean of the squares of individual molecular speeds: v_rms = √(3 R T / M).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q33: Write the formula for most probable speed v_mp of gas molecules.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> v_mp = √(2 R T / M).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q34: Write the formula for average speed v_avg of gas molecules.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> v_avg = √(8 R T / π M).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q35: What is the ratio of v_mp : v_avg : v_rms?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> √2 : √(8/π) : √3 ≈ 1 : 1.128 : 1.225.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q36: Define Degrees of Freedom (f) of a gas molecule.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> The total number of independent coordinates or modes of motion required to completely specify molecular state.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q37: State the Law of Equi-partition of Energy.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> In thermal equilibrium, total energy of gas is distributed equally among degrees of freedom, each carrying ½ k_B T per molecule.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q38: What is the number of degrees of freedom for a monoatomic gas molecule?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> 3 translational degrees of freedom (f = 3).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q39: What is the number of degrees of freedom for a rigid diatomic gas molecule?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> 5 degrees of freedom (3 translational + 2 rotational).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q40: Write the expression for molar specific heat C_v in terms of degrees of freedom f.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> C_v = (f / 2) R.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q41: Write the expression for molar specific heat C_p in terms of degrees of freedom f.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> C_p = (f / 2 + 1) R.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q42: Write the expression for adiabatic index γ = C_p / C_v in terms of degrees of freedom f.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> γ = 1 + (2 / f).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q43: Define Mean Free Path (λ) of a gas molecule.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> The average distance traveled by a molecule between two consecutive collisions.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q44: Write the formula for mean free path λ in terms of number density n and molecular diameter d.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> λ = 1 / (√2 π n d²).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q45: How does mean free path λ depend on absolute temperature T at constant pressure?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> λ ∝ T (at constant P).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q46: How does mean free path λ depend on pressure P at constant temperature?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> λ ∝ 1/P (at constant T).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q47: Write the numerical value and units of Universal Gas Constant R.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> R = 8.314 J mol⁻¹ K⁻¹.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q48: Write the numerical value and units of Boltzmann Constant k_B.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> k_B = 1.3806 × 10⁻²³ J K⁻¹.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q49: Write the numerical value and units of Avogadro's Number N_A.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> N_A = 6.022 × 10²³ mol⁻¹.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q50: What is the average kinetic energy per molecule of a rigid diatomic gas?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> E_k = (5/2) k_B T.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q51: Why do light gases like Hydrogen escape Earth's atmosphere while heavy gases remain?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> RMS speed of H₂ at upper atmosphere temps exceeds Earth's escape speed (11.2 km/s).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q52: What is the value of v_rms of gas molecules at absolute zero temperature (0 K)?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Zero (v_rms = 0).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q53: How does rms speed of a gas depend on its molar mass M at constant temperature?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> v_rms ∝ 1 / √M (Lighter molecules move faster).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q54: Why is pressure of a gas inside a container independent of shape of container?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Because collisions are completely random in all 3 spatial directions.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 12px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q55: What is Avogadro's Hypothesis?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Ans:</b> Equal volumes of all gases under same conditions of temperature and pressure contain equal numbers of molecules.</p>\n    </div><h2 style=\"color: #42A5F5; border-bottom: 2px solid #42A5F5; padding-bottom: 6px; margin-top: 30px;\">SECTION 3: SHORT ANSWER QUESTIONS (SAs 56 - 85)</h2>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q56: State the main postulates/assumptions of Kinetic Theory of Gases.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Large number of identical spherical point-mass molecules.\n2. Molecules are in continuous random motion obeying Newton's laws.\n3. Collisions are perfectly elastic with zero intermolecular forces except during impact.\n4. Molecular volume is negligible compared to container volume.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q57: Derive kinetic interpretation of temperature and show that average KE per molecule is E_k = 3/2 k_B T.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> P = ⅓ (N m / V) v_rms² ⇒ P V = ⅓ N m v_rms² = ⅔ N (½ m v_rms²). Since P V = N k_B T, ⅔ N E_k = N k_B T ⇒ E_k = 3/2 k_B T.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q58: Define RMS speed, Average speed, and Most Probable speed. Write their mathematical expressions and compare them.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. v_rms = √(3 R T / M).\n2. v_avg = √(8 R T / π M).\n3. v_mp = √(2 R T / M).\nComparison: v_mp < v_avg < v_rms (Ratio 1 : 1.128 : 1.225).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q59: State Law of Equi-partition of Energy. Calculate total molar internal energy U and C_v for monoatomic and rigid diatomic gases.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> 1. Monoatomic (f = 3): U = 3 × (½ R T) = 3/2 R T ⇒ C_v = dU/dT = 3/2 R.\n2. Rigid Diatomic (f = 5): U = 5 × (½ R T) = 5/2 R T ⇒ C_v = 5/2 R.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q60: Derive expression for adiabatic index γ = C_p / C_v for monoatomic, diatomic, and polyatomic gases.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> C_v = (f/2) R, C_p = (f/2 + 1) R ⇒ γ = C_p / C_v = 1 + 2/f.\n1. Monoatomic (f=3): γ = 1 + 2/3 = 5/3 = 1.67.\n2. Diatomic (f=5): γ = 1 + 2/5 = 7/5 = 1.40.\n3. Polyatomic (f=6): γ = 1 + 2/6 = 4/3 = 1.33.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q61: Define Mean Free Path λ. Derive expression λ = 1 / (√2 π n d²) using collision cylinder model.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> In time t, a molecule of diameter d sweeps out collision cylinder of volume π d² (v t). Number of collisions = n π d² v t. Mean free path λ = (v t) / (n π d² v t) = 1 / (π n d²). Considering motion of all target molecules adds factor √2, giving λ = 1 / (√2 π n d²).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q62: Explain how mean free path λ varies with: (i) Temperature T at constant pressure, (ii) Pressure P at constant temperature.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Substitute n = P / (k_B T) into λ = 1 / (√2 π n d²):\n1. λ = k_B T / (√2 π d² P). At constant P, λ ∝ T (Heated gas expands, increasing path).\n2. At constant T, λ ∝ 1/P (Higher P increases number density n, decreasing path).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q63: Calculate rms speed of Oxygen (O₂) molecules at 27°C (Molar mass M = 32 g/mol, R = 8.314 J/mol K).</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> T = 27 + 273 = 300 K, M = 0.032 kg/mol. v_rms = √(3 R T / M) = √(3 × 8.314 × 300 / 0.032) = √(7482.6 / 0.032) = √(233831.25) ≈ 483.56 m/s.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q64: At what temperature will rms speed of Hydrogen gas molecules be double its value at 0°C?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> T₁ = 273 K. v_rms ∝ √T. v_rms' = 2 v_rms ⇒ √T₂ = 2 √T₁ ⇒ T₂ = 4 T₁ = 4 × 273 = 1092 K = 819°C.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q65: Find the total kinetic energy of 8 g of Oxygen gas at 27°C (M = 32 g/mol, R = 8.314 J/mol K).</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Moles n = 8 / 32 = 0.25 mol. Total KE U = n × (5/2) R T = 0.25 × 2.5 × 8.314 × 300 = 0.625 × 2494.2 = 1558.875 Joules.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q66: Calculate mean free path of Nitrogen molecules at STP (d = 2 × 10⁻¹⁰ m, n = 2.7 × 10²⁵ m⁻³).</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> λ = 1 / (√2 π n d²) = 1 / (1.414 × 3.1416 × 2.7×10²⁵ × (2×10⁻¹⁰)²) = 1 / (4.442 × 2.7×10²⁵ × 4×10⁻²⁰) = 1 / (4.797 × 10⁶) = 2.08 × 10⁻⁷ m = 208 nm.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q67: A container holds 1 mole Helium and 2 moles Nitrogen at 300 K. Calculate total internal energy of mixture.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> U_He = 1 × (3/2) R T = 1.5 R T. U_N2 = 2 × (5/2) R T = 5.0 R T. Total U = 6.5 R T = 6.5 × 8.314 × 300 = 16,212.3 Joules.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q68: Why is C_p - C_v = R valid for all ideal gases regardless of atomicity?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Because C_v = (f/2) R and C_p = (f/2 + 1) R. Subtracting gives C_p - C_v = [(f/2 + 1) - f/2] R = R.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q69: Calculate the temperature at which rms speed of Argon atom (M = 40 g/mol) equals 500 m/s.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> v_rms² = 3 R T / M ⇒ T = M v_rms² / (3 R) = (0.040 × 500²) / (3 × 8.314) = (0.040 × 250000) / 24.942 = 10000 / 24.942 = 400.9 K = 127.9°C.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q70: Explain why Maxwell-Boltzmann speed distribution curve broadens and shifts right at higher temperature.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> At higher T, total area under N(v) curve remains constant (N_total), but fraction of high-speed molecules increases, shifting peak v_mp = √(2RT/M) rightward and flattening the peak.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q71: A gas at 27°C and 1 atm pressure has density 1.2 kg/m³. Calculate rms speed of its molecules.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> P = ⅓ ρ v_rms² ⇒ v_rms = √(3 P / ρ) = √(3 × 1.013 × 10⁵ / 1.2) = √(303900 / 1.2) = √(253250) ≈ 503.24 m/s.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q72: Why does temperature of a gas remain constant during isothermal expansion even though work is done?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Because heat Q is simultaneously supplied from external reservoir equal to work done W, maintaining constant internal energy ΔU = 0 and temperature ΔT = 0.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q73: Calculate Boltzmann constant k_B given R = 8.314 J/mol K and N_A = 6.022 × 10²³ mol⁻¹.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> k_B = R / N_A = 8.314 / (6.022 × 10²³) = 1.3806 × 10⁻²³ J K⁻¹.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q74: Calculate the average translational KE of 1 molecule of any ideal gas at 27°C.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> T = 300 K. E_k = 3/2 k_B T = 1.5 × 1.3806×10⁻²³ × 300 = 6.2127 × 10⁻²¹ Joules.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q75: Calculate the average translational KE of 1 mole of an ideal gas at 27°C.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> T = 300 K. E_k_mole = 3/2 R T = 1.5 × 8.314 × 300 = 3741.3 Joules.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q76: Estimate the molecular diameter d of Nitrogen if mean free path λ = 100 nm at number density n = 2.5 × 10²⁵ m⁻³.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> λ = 1 / (√2 π n d²) ⇒ d² = 1 / (√2 π n λ) = 1 / (1.414 × 3.1416 × 2.5×10²⁵ × 10⁻⁷) = 1 / 1.1105×10¹ = 9.005 × 10⁻²⁰ m² ⇒ d ≈ 3.0 × 10⁻¹⁰ m = 3 Å.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q77: Why is real gas pressure lower than ideal gas pressure at high density?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Attractive intermolecular forces pull inward on boundary molecules, reducing impact momentum on container wall (van der Waals correction P + a/V²).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q78: Why is real gas volume smaller than ideal gas volume at high pressure?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Finite volume of gas molecules (co-volume b) reduces free space available for motion (V - b).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q79: Calculate adiabatic index γ for a gas mixture of 1 mole monoatomic gas (γ₁=5/3) and 1 mole diatomic gas (γ₂=7/5).</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> C_v_mix = (1×1.5R + 1×2.5R) / 2 = 2.0 R. C_p_mix = (1×2.5R + 1×3.5R) / 2 = 3.0 R. γ_mix = 3.0 R / 2.0 R = 1.50.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q80: Show that for an ideal gas, pressure P is equal to 2/3 of kinetic energy density E_k.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> P = ⅓ ρ v_rms² = ⅔ (½ ρ v_rms²) = ⅔ E_k.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q81: Find the ratio of rms speed of Helium (M=4) to Neon (M=20) at same temperature.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> v_He / v_Ne = √(M_Ne / M_He) = √(20 / 4) = √5 ≈ 2.236.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q82: Calculate the temperature at which kinetic energy of gas molecule is double its KE at 27°C.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> T₁ = 300 K. KE ∝ T. KE₂ = 2 KE₁ ⇒ T₂ = 2 T₁ = 600 K = 327°C.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q83: Define Avogadro's Number N_A and state its significance in kinetic theory.</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> N_A = 6.022 × 10²³ mol⁻¹ is the number of molecules per mole, bridging microscopic molecular quantities to macroscopic thermodynamic observables (R = N_A k_B).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q84: Why does moist air have lower density than dry air at same T and P?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Molar mass of water vapor H₂O (18 g/mol) is significantly less than average molar mass of dry air (N₂ + O₂ ≈ 29 g/mol).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 14px 16px; margin: 14px 0;\">\n      <b style=\"color: #42A5F5; font-size: 15.5px;\">Q85: What is Brownian motion and how does it support Kinetic Theory?</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6;\"><b>Solution:</b> Continuous random zig-zag motion of microscopic suspended particles in fluid caused by irregular, unequal impacts of surrounding fast-moving molecules, providing direct visual proof of Kinetic Theory.</p>\n    </div><h2 style=\"color: #42A5F5; border-bottom: 2px solid #42A5F5; padding-bottom: 6px; margin-top: 30px;\">SECTION 4: LONG ANSWER QUESTIONS (LAs 86 - 100)</h2>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q86: Derive an expression for pressure exerted by an ideal gas on container walls P = ⅓ ρ v_rms² from Kinetic Theory postulates.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Postulates setup in cubic box L³.\n2. Single molecule m with (v_x, v_y, v_z) rebounds off right wall: Δp = 2 m v_x.\n3. Time between wall collisions Δt = 2 L / v_x. Force F_1 = Δp / Δt = m v_x² / L.\n4. Total force F = (m/L) ∑ v_xi². Pressure P = F / L² = (m/L³) N v_rms_x² = (m N / V) (⅓ v_rms²) = ⅓ ρ v_rms².</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q87: Explain kinetic interpretation of temperature. Derive expressions for: (i) RMS speed v_rms, (ii) Average speed v_avg, (iii) Most probable speed v_mp of gas molecules.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. P V = ⅓ N m v_rms² = ⅔ N (½ m v_rms²) = N k_B T ⇒ E_k = 3/2 k_B T (T ∝ translational KE).\n2. v_rms = √(3 R T / M).\n3. v_avg = √(8 R T / π M).\n4. v_mp = √(2 R T / M).</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q88: State and prove Law of Equi-partition of Energy. Derive expressions for C_v, C_p, and γ for monoatomic, diatomic (rigid & vibrating), and polyatomic gases.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Law statement: ½ k_B T per degree of freedom.\n2. U = (f/2) R T, C_v = (f/2) R, C_p = (f/2 + 1) R, γ = 1 + 2/f.\n3. Monoatomic (f=3): C_v=1.5R, C_p=2.5R, γ=1.67.\n4. Diatomic rigid (f=5): C_v=2.5R, C_p=3.5R, γ=1.40.\n5. Diatomic vibrating (f=7): C_v=3.5R, C_p=4.5R, γ=1.29.\n6. Polyatomic (f=6): C_v=3.0R, C_p=4.0R, γ=1.33.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q89: What is Mean Free Path? Derive expression λ = 1 / (√2 π n d²) using collision cylinder model. Discuss factors affecting mean free path.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Definition of λ.\n2. Collision cylinder of diameter 2d: area π d², length v t. Collisions Z = n π d² v t ⇒ λ_stationary = 1 / (π n d²).\n3. Maxwell relative velocity factor √2: λ = 1 / (√2 π n d²).\n4. Factors: λ ∝ T (at const P), λ ∝ 1/P (at const T), λ ∝ 1/ρ.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q90: State Avogadro's Law. Derive Avogadro's law and Graham's law of diffusion from kinetic theory of gases.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Avogadro's Law: P₁ V₁ = ⅓ N₁ m₁ v_rms1² and P₂ V₂ = ⅓ N₂ m₂ v_rms2². If P₁=P₂, V₁=V₂, T₁=T₂ ⇒ ½ m₁ v_rms1² = ½ m₂ v_rms2² ⇒ N₁ = N₂.\n2. Graham's Law: v_rms = √(3P/ρ) ⇒ Rate of diffusion r ∝ v_rms ∝ 1/√ρ.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q91: A gas cylinder contains 12 L of Oxygen gas at 27°C and pressure 15 atm. Calculate: (i) Number of moles, (ii) Total mass of gas, (iii) Total translational KE, (iv) RMS speed of molecules.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. V = 0.012 m³, T = 300 K, P = 15 × 1.013×10⁵ = 1.5195 × 10⁶ Pa.\n2. n = P V / (R T) = (1.5195×10⁶ × 0.012) / (8.314 × 300) = 18234 / 2494.2 = 7.31 moles.\n3. Mass m = 7.31 × 32 g = 233.92 g = 0.234 kg.\n4. Total KE U = n × 2.5 R T = 7.31 × 2.5 × 8.314 × 300 = 45,584 Joules.\n5. v_rms = √(3 × 8.314 × 300 / 0.032) = 483.56 m/s.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q92: Explain Maxwell-Boltzmann distribution of molecular speeds. Draw N(v) vs v curves for a gas at two temperatures T₁ and T₂ (T₂ > T₁) and state 4 key features.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Feature 1: N(v) starts from zero at v=0, reaches peak at v_mp, and approaches zero at v→∞.\n2. Feature 2: Peak v_mp = √(2RT/M) shifts right to higher speeds at higher T₂.\n3. Feature 3: Curve broadens and flattens at T₂ while total enclosed area N remains constant.\n4. Feature 4: Fraction of high-speed molecules increases exponentially with T.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q93: A mixture of 2 moles Helium (Monoatomic, f=3) and 3 moles Argon (Monoatomic, f=3) and 1 mole Nitrogen (Diatomic rigid, f=5) is enclosed at temp T. Calculate: (i) Total internal energy U, (ii) Equivalent C_v_mix, (iii) Equivalent γ_mix.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Total moles n_total = 2 + 3 + 1 = 6 moles.\n2. Internal Energy U = (2×1.5R T) + (3×1.5R T) + (1×2.5R T) = 3R T + 4.5R T + 2.5R T = 10.0 R T.\n3. C_v_mix = U / (n_total T) = 10.0 R / 6 = 5/3 R = 1.67 R.\n4. C_p_mix = C_v_mix + R = 1.67 R + R = 2.67 R.\n5. γ_mix = C_p_mix / C_v_mix = 2.67 R / 1.67 R = 1.60.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q94: Calculate the root-mean-square speed, average speed, and most probable speed of Nitrogen molecules at 300 K (M = 28 g/mol, R = 8.314 J/mol K).</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. v_rms = √(3 × 8.314 × 300 / 0.028) = √(7482.6 / 0.028) = √(267235.7) = 516.95 m/s.\n2. v_avg = √(8 × 8.314 × 300 / (3.1416 × 0.028)) = √(19953.6 / 0.08796) = √(226837) = 476.27 m/s.\n3. v_mp = √(2 × 8.314 × 300 / 0.028) = √(4988.4 / 0.028) = √(178157.1) = 422.09 m/s.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q95: Explain the concept of Degrees of Freedom. State Law of Equi-partition of Energy and apply it to calculate molar specific heats C_v and C_p for water vapor (non-linear triatomic f=6).</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Water vapor H₂O has 3 translational + 3 rotational degrees of freedom (f = 6).\n2. U = 6 × (½ R T) = 3 R T.\n3. C_v = dU/dT = 3 R.\n4. C_p = C_v + R = 4 R.\n5. Ratio γ = C_p / C_v = 4/3 ≈ 1.33.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q96: At what temperature will the rms speed of Hydrogen gas molecules (M=2) be equal to the escape speed from Earth's surface (11.2 km/s)?</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. v_rms = 11.2 km/s = 11,200 m/s.\n2. v_rms² = 3 R T / M ⇒ T = M v_rms² / (3 R) = (0.002 × 11200²) / (3 × 8.314) = (0.002 × 125,440,000) / 24.942 = 250,880 / 24.942 = 10,058.5 K ≈ 10,060 K.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q97: Estimate the total number of air molecules in a room of dimensions 5 m × 4 m × 3 m at 27°C and 1 atm pressure (1.013 × 10⁵ Pa, k_B = 1.38 × 10⁻²³ J/K).</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Volume V = 5 × 4 × 3 = 60 m³.\n2. Temp T = 27 + 273 = 300 K.\n3. P V = N k_B T ⇒ N = P V / (k_B T) = (1.013 × 10⁵ × 60) / (1.38 × 10⁻²³ × 300) = 6.078 × 10⁶ / (4.14 × 10⁻²¹) = 1.468 × 10²⁷ molecules.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q98: Calculate the mean free path and collision frequency of Helium gas atoms at STP (d = 2.0 Å = 2.0 × 10⁻¹⁰ m, n = 2.7 × 10²⁵ m⁻³, M = 4 g/mol).</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Mean free path λ = 1 / (√2 π n d²) = 1 / (1.414 × 3.1416 × 2.7×10²⁵ × 4×10⁻²⁰) = 2.08 × 10⁻⁷ m = 208 nm.\n2. v_rms = √(3 × 8.314 × 273 / 0.004) = √(6809.16 / 0.004) = 1304.7 m/s.\n3. Collision frequency f_col = v_rms / λ = 1304.7 / (2.08 × 10⁻⁷) = 6.27 × 10⁹ collisions/second.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q99: Explain how kinetic theory accounts for: (i) Boyle's Law, (ii) Charles's Law, (iii) Dalton's Law of Partial Pressures.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Boyle's Law: P = ⅓ (N m / V) v_rms². At const T, v_rms is const ⇒ P V = Const.\n2. Charles's Law: V = ⅓ (N m / P) v_rms². Since v_rms² ∝ T ⇒ V ∝ T.\n3. Dalton's Law: Total pressure P = P₁ + P₂ + ... = ⅓ ρ₁ v_rms1² + ⅓ ρ₂ v_rms2² + ... equal to sum of partial pressures.</p>\n    </div>\n    <div style=\"background: rgba(66, 165, 245, 0.04); border-left: 4px solid #42A5F5; border-radius: 6px; padding: 16px; margin: 16px 0;\">\n      <b style=\"color: #42A5F5; font-size: 16px;\">Q100: Describe van der Waals equation of state for real gases: (P + a/V²)(V - b) = R T. Explain physical significance of corrections 'a' and 'b'.</b>\n      <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px; line-height: 1.6; white-space: pre-line;\"><b>Comprehensive Solution:</b>\n1. Pressure correction (a/V²): Accounts for attractive intermolecular forces pulling boundary molecules inward, reducing wall impact.\n2. Volume correction (b): Co-volume accounting for finite size of gas molecules, reducing free volume available for motion.\n3. At low P (large V) and high T, a/V² and b become negligible, restoring ideal gas equation P V = R T.</p>\n    </div></div>";
